class Chip8 {
  constructor() {
    this.memory = new Uint8Array(4096);
    this.V = new Uint8Array(16);
    this.I = 0;
    this.pc = 0x200;
    this.stack = [];
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display = new Uint8Array(64 * 32);
    this.keys = new Uint8Array(16);
    this.waitingForKey = false;
    this.waitReg = 0;
    this.drawFlag = false;
    this.beepFlag = false;
    this.halted = false;
    this.loadFonts();
  }
  loadFonts() { this.memory.set(FONT_SET, 0x050); }
  reset() {
    this.memory.fill(0);
    this.V.fill(0);
    this.I = 0;
    this.pc = 0x200;
    this.stack = [];
    this.delayTimer = 0;
    this.soundTimer = 0;
    this.display.fill(0);
    this.keys.fill(0);
    this.waitingForKey = false;
    this.drawFlag = true;
    this.beepFlag = false;
    this.halted = false;
    this.loadFonts();
  }
  loadROM(bytes) {
    this.reset();
    const len = Math.min(bytes.length, 4096 - 0x200);
    this.memory.set(bytes.subarray(0, len), 0x200);
  }
  keyDown(k) {
    this.keys[k] = 1;
    if (this.waitingForKey) {
      this.V[this.waitReg] = k;
      this.waitingForKey = false;
      this.pc = (this.pc + 2) & 0xFFF;
    }
  }
  keyUp(k) { this.keys[k] = 0; }
  tickTimers() {
    if (this.delayTimer > 0) this.delayTimer--;
    if (this.soundTimer > 0) {
      this.soundTimer--;
      if (this.soundTimer === 0) this.beepFlag = true;
    }
  }
  step() {
    if (this.waitingForKey) return; // Fx0A: block until a key arrives
    if (this.pc < 0x200 || this.pc > 0xFFE) { this.halted = true; return; }
    const op = (this.memory[this.pc] << 8) | this.memory[this.pc + 1];
    const nnn = op & 0x0FFF;
    const n = op & 0x000F;
    const x = (op >> 8) & 0x0F;
    const y = (op >> 4) & 0x0F;
    const kk = op & 0x00FF;
    const V = this.V;
    let pc = (this.pc + 2) & 0xFFF;
    switch (op & 0xF000) {
      case 0x0000:
        if (op === 0x00E0) this.display.fill(0);
        else if (op === 0x00EE) {
          if (this.stack.length === 0) { this.halted = true; return; }
          pc = this.stack.pop();
        }
        break; // 0nnn SYS is ignored (modern interpreters)
      case 0x1000: pc = nnn; break;
      case 0x2000: this.stack.push(this.pc + 2); pc = nnn; break;
      case 0x3000: if (V[x] === kk) pc = (pc + 2) & 0xFFF; break;
      case 0x4000: if (V[x] !== kk) pc = (pc + 2) & 0xFFF; break;
      case 0x5000: if (V[x] === V[y]) pc = (pc + 2) & 0xFFF; break;
      case 0x6000: V[x] = kk; break;
      case 0x7000: V[x] = (V[x] + kk) & 0xFF; break;
      case 0x8000:
        switch (n) {
          case 0x0: V[x] = V[y]; break;
          case 0x1: V[x] |= V[y]; break;
          case 0x2: V[x] &= V[y]; break;
