          case 0x4: { const s = V[x] + V[y]; V[x] = s & 0xFF; V[0xF] = s > 0xFF ? 1 : 0; break; }
          case 0x5: { const b = V[x] >= V[y] ? 1 : 0; V[x] = (V[x] - V[y]) & 0xFF; V[0xF] = b; break; }
          case 0x6: { const c = V[x] & 1; V[x] >>= 1; V[0xF] = c; break; }
          case 0x7: { const b = V[y] >= V[x] ? 1 : 0; V[x] = (V[y] - V[x]) & 0xFF; V[0xF] = b; break; }
          case 0xE: { const c = (V[x] >> 7) & 1; V[x] = (V[x] << 1) & 0xFF; V[0xF] = c; break; }
        }
