            this.memory[(this.I + 1) & 0xFFF] = Math.floor(v / 10) % 10;
            this.memory[(this.I + 2) & 0xFFF] = v % 10;
            break;
          }
          case 0x55: for (let i = 0; i <= x; i++) this.memory[(this.I + i) & 0xFFF] = V[i]; break;
          case 0x65: for (let i = 0; i <= x; i++) V[i] = this.memory[(this.I + i) & 0xFFF]; break;
