// ============================ DISASSEMBLER ============================
function disassemble(op) {
  const nnn = op & 0x0FFF, n = op & 0xF, x = (op >> 8) & 0xF, y = (op >> 4) & 0xF, kk = op & 0xFF;
  const hx = v => '0x' + v.toString(16).toUpperCase().padStart(3, '0');
  const hb = v => '0x' + v.toString(16).toUpperCase().padStart(2, '0');
  switch (op & 0xF000) {
    case 0x0000:
      if (op === 0x00E0) return 'CLS';
      if (op === 0x00EE) return 'RET';
      return 'SYS ' + hx(nnn);
    case 0x1000: return 'JP ' + hx(nnn);
    case 0x2000: return 'CALL ' + hx(nnn);
    case 0x3000: return 'SE V' + x.toString(16).toUpperCase() + ', ' + hb(kk);
    case 0x4000: return 'SNE V' + x.toString(16).toUpperCase() + ', ' + hb(kk);
    case 0x5000: return 'SE V' + x.toString(16).toUpperCase() + ', V' + y.toString(16).toUpperCase();
    case 0x6000: return 'LD V' + x.toString(16).toUpperCase() + ', ' + hb(kk);
    case 0x7000: return 'ADD V' + x.toString(16).toUpperCase() + ', ' + hb(kk);
    case 0x8000: {
      const ops = ['LD', 'OR', 'AND', 'XOR', 'ADD', 'SUB', 'SHR', 'SUBN'];
      if (n === 0xE) return 'SHL V' + x.toString(16).toUpperCase();
      if (n <= 7) return ops[n] + ' V' + x.toString(16).toUpperCase() + ', V' + y.toString(16).toUpperCase();
      return '???';
    }
    case 0x9000: return 'SNE V' + x.toString(16).toUpperCase() + ', V' + y.toString(16).toUpperCase();
    case 0xA000: return 'LD I, ' + hx(nnn);
    case 0xB000: return 'JP V0, ' + hx(nnn);
    case 0xC000: return 'RND V' + x.toString(16).toUpperCase() + ', ' + hb(kk);
    case 0xD000: return 'DRW V' + x.toString(16).toUpperCase() + ', V' + y.toString(16).toUpperCase() + ', ' + n;
    case 0xE000:
      if (kk === 0x9E) return 'SKP V' + x.toString(16).toUpperCase();
      if (kk === 0xA1) return 'SKNP V' + x.toString(16).toUpperCase();
      return '???';
    case 0xF000: {
      const m = {
        0x07: 'LD V' + x.toString(16).toUpperCase() + ', DT',
        0x0A: 'LD V' + x.toString(16).toUpperCase() + ', K',
        0x15: 'LD DT, V' + x.toString(16).toUpperCase(),
        0x18: 'LD ST, V' + x.toString(16).toUpperCase(),
        0x1E: 'ADD I, V' + x.toString(16).toUpperCase(),
        0x29: 'LD F, V' + x.toString(16).toUpperCase(),
        0x33: 'LD B, V' + x.toString(16).toUpperCase(),
        0x55: 'LD [I], V' + x.toString(16).toUpperCase(),
        0x65: 'LD V' + x.toString(16).toUpperCase() + ', [I]'
      };
      return m[kk] || '???';
    }
  }
  return '???';
}
